-- Fictional players, clubs, sessions and match facts for the viewer-aware Player reads (period leaderboards,
-- profile, RTR ID, rank, games, stats, my profile). GENERATED once by a script; edit by hand from here on and rerun
-- apps/api/testdata/tools/capture-signedin-profile.test.mjs after any change. Foreign key checks are off for this load.
BEGIN;
SET LOCAL session_replication_role = replica;

SELECT v.player_id::uuid, v.skill_level_id, v.numeric_rank, v.state::rank_state, '{}'::jsonb, (SELECT id FROM ranking_policy_versions ORDER BY version LIMIT 1), 'rank-test-v1',
       TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-11-01 00:00:00+00', TIMESTAMPTZ '2026-11-01 00:00:00+00', 1, TIMESTAMPTZ '2027-01-01 00:00:00+00', v.recent, true, now()
FROM (VALUES ('d3000000-0000-4000-8000-000000000001', 4::smallint, 61.5::numeric, 'established', 7), ('d3000000-0000-4000-8000-000000000002', 2::smallint, 40.0::numeric, 'provisional', 2), ('d3000000-0000-4000-8000-000000000003', 6::smallint, 75.0::numeric, 'established', 9), ('d3000000-0000-4000-8000-000000000006', 3::smallint, 50.0::numeric, 'provisional', 3)) AS v(player_id, skill_level_id, numeric_rank, state, recent);
COMMIT;
